import{_ as o,C as s,o as t,c as p,ag as a,E as l}from"./chunks/framework.DUTPmUpA.js";const c="/_assets/BlackSameAoudad.MOgozQWT.mp4",i="/_assets/ZsmLQA3.CtXQj8AN.png",r="/_assets/o3Gv7-783de89488.D8COsoQt.jpg",v=JSON.parse('{"title":"DOTAScenePanel","description":"","frontmatter":{"title":"DOTAScenePanel","author":"DoctorGester","steamId":"76561198046920629","date":"02.04.2016"},"headers":[],"relativePath":"panorama/dotascenepanel.md","filePath":"panorama/dotascenepanel.md"}'),d={name:"panorama/dotascenepanel.md"};function u(h,e,m,b,q,_){const n=s("StaticVideo");return t(),p("div",null,[e[0]||(e[0]=a('<h1 id="dotascenepanel" tabindex="-1">DOTAScenePanel <a class="header-anchor" href="#dotascenepanel" aria-label="Permalink to &quot;DOTAScenePanel&quot;">​</a></h1><p>В этом уроке мы рассмотрим приемы, которые можно проделать с недокументированным классом DOTAScenePanel в панораме.</p><p>Возможно, вы видели его использование, если просмотрели источники в главном меню. Эта панель позволяет нам отображать 3D-контент в панораме. Возможно, вы пробовали использовать его самостоятельно. Довольно легко настроить простую панель для отображения единицы измерения с помощью кода типа</p><p><code>&lt;DOTAScenePanel style=&quot;width:400px;height:400px;&quot; unit=&quot;npc_dota_hero_sven&quot; particleonly=&quot;false&quot;/&gt;</code></p><p>Обратите внимание: <code>particleonly=&#39;false&#39;</code> требуется для <code>DOTAScenePanel</code> для правильного отображения чего-либо, кроме частиц.</p><p>Подобный код используется для отображения героев в арсенале. Эта панель также не имеет пользовательских динамических свойств, а это означает, что мы не можем изменить единицу измерения после создания панели. В арсенале модели героев можно вращать, и это поведение можно включить с помощью набора <code>allowrotation=&quot;true&quot;</code>. Однако этот параметр несовместим с пользовательскими фоновыми картами.</p><h2 id="фоновые-карты" tabindex="-1">Фоновые карты <a class="header-anchor" href="#фоновые-карты" aria-label="Permalink to &quot;Фоновые карты&quot;">​</a></h2><p>Но подождите, это еще не все! DOTAScenePanel принимает параметр «map», который указывает на определенный тип vmaps — фоновые карты. Вы можете найти их в браузере ресурсов в фоновой папке. Эти vmaps принимают только определенный набор объектов и отображаются в панораме с помощью камер. Давайте продолжим, создав простую фоновую карту.</p><h3 id="настроика-карты" tabindex="-1">Настройка карты <a class="header-anchor" href="#настроика-карты" aria-label="Permalink to &quot;Настройка карты&quot;">​</a></h3><p>Запустите редактор молотков и создайте новую карту. Сохраните его в папке с картами как <code>background.vmap</code>. Перейдите в Карта -&gt; Свойства карты (Ctrl-Shift-P) и установите флажок «Компилировать как фоновую карту».</p><p>Используйте инструмент «Entity Tool» (Shift-E) и выберите объект <code>prop_dynamic</code>, затем щелкните где-нибудь в мире, чтобы разместить его. Выберите этот вновь помещенный объект в планировщике и измените его свойство <code>World Model</code> на <code>models/courier/donkey_unicorn/donkey_unicorn.vmdl</code>.</p><p>Теперь ваша кинозвезда готова к показу. Вы также можете изменить поле <code>Default Animation</code> на <code>idle</code> или любую строку из записей модели.</p><p>Теперь у нас есть <em>action</em>, но по-прежнему отсутствуют <em>lights</em> и <em>camera</em>. Начнем со света — с помощью Entity Tool (Shift-E) создайте объект <code>env_global_light</code>. Например, измените его имя на <code>light</code>.</p><p>Как и в случае с <code>env_global_light</code>, создайте объект <code>point_camera</code>. Выберите вновь созданную камеру, переместите камеру-молот так, чтобы вы могли видеть осла, и нажмите <code>View - Align Selection to Active Camera</code>.</p><p>На последнем шаге выберите свою камеру и дайте ей имя в свойствах, например <code>camera1</code>. Сохраните свою карту и постройте ее (F9).</p><h3 id="настроика-панорамы" tabindex="-1">Настройка панорамы <a class="header-anchor" href="#настроика-панорамы" aria-label="Permalink to &quot;Настройка панорамы&quot;">​</a></h3><p>Я не буду описывать, как настроить базовую среду панорамы. Если у вас возникли проблемы с отображением простых панелей, обратитесь к <a href="https://developer.valvesoftware.com/wiki/Dota_2_Workshop_Tools/Panorama" target="_blank" rel="noreferrer">https://developer.valvesoftware.com/wiki/Dota_2_Workshop_Tools/Panorama</a>. Когда вы будете готовы к работе, просто добавьте <code>&lt;DOTAScenePanel style=&quot;width:400px;height:400px;&quot; map=&quot;background&quot; light=&quot;light&quot; camera=&quot;camera1&quot; particleonly=&quot;false&quot;/&gt;</code> в свой XML, и вы увидите свою кинозвезду-осла во всей ее красе. Это не займет у вас больше 10 минут.</p>',17)),l(n,{path:c}),e[1]||(e[1]=a('<p>Теперь перейдем к продвинутой части.</p><h2 id="та-часть-где-магия-становится-реальностью" tabindex="-1">Та часть, где магия становится реальностью <a class="header-anchor" href="#та-часть-где-магия-становится-реальностью" aria-label="Permalink to &quot;Та часть, где магия становится реальностью&quot;">​</a></h2><h3 id="единицы-с-косметикои" tabindex="-1">Единицы с косметикой <a class="header-anchor" href="#единицы-с-косметикои" aria-label="Permalink to &quot;Единицы с косметикой&quot;">​</a></h3><p>Мы можем легко создать сцену, подобную «единице», используя тип сущности <code>portrait_world_unit</code>. Этот объект поддерживает все виды юнитов, а также определения косметических предметов. Причуда здесь в том, что вам нужно войти в режим редактирования необработанных свойств, чтобы назначить отображаемому объекту героя. Все свойства определений предметов относятся к различным слотам загрузки и принимают идентификаторы предметов. Список идентификаторов предметов можно найти <a href="https://github.com/dotabuff/d2vpk/blob/master/dota_pak01/scripts/items/items_game.txt" target="_blank" rel="noreferrer">here</a>.</p><p><img src="'+i+'" alt="Lina is awesome" title="Example"></p><h3 id="несколько-камер" tabindex="-1">Несколько камер <a class="header-anchor" href="#несколько-камер" aria-label="Permalink to &quot;Несколько камер&quot;">​</a></h3><p>Это довольно просто: <code>DOTAScenePanel</code> также принимает в определении параметр <code>camera</code>, который попытается найти камеру с указанным именем.</p><p><img src="'+r+`" alt="/images/external/o3Gv7-783de89488.jpg"> Важно отметить, что повторная компиляция карты меняет внешний вид панели панорамы без перезапуска карты, но вы не можете изменить его во время выполнения. В следующих частях вы поймете, как добиться того же результата.</p><h3 id="динамическая-загрузка-макета" tabindex="-1">Динамическая загрузка макета <a class="header-anchor" href="#динамическая-загрузка-макета" aria-label="Permalink to &quot;Динамическая загрузка макета&quot;">​</a></h3><p>Поскольку единственное, что учитывает DOTAScenePanel, — это собственное определение макета, нам придется предоставить его с самого начала. К счастью, мы можем загрузить макет из строки, изменив при этом определение.</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>js</span></span>
<span class="line"><span>var camera = &quot;camera1&quot;;</span></span>
<span class="line"><span>var style = &quot;width:400px;height:400px;&quot;;</span></span>
<span class="line"><span>if (someCondition) {</span></span>
<span class="line"><span>    camera = &quot;camera2&quot;;</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span></span></span>
<span class="line"><span>var sceneContainer = $(&quot;#SomeContainer&quot;);</span></span>
<span class="line"><span>sceneContainer.BCreateChildren(&quot;&lt;DOTAScenePanel style=&#39;&quot; + style + &quot;&#39; map=&#39;background&#39; particleonly=&#39;false&#39; light=&#39;light&#39; camera=&#39;&quot; + camera + &quot;&#39;&quot;/&gt;&quot;);</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br></div></div><p>Как вы могли заметить, вам придется обернуть все это в &#39;&#39;, а также предоставить исходный контейнер для макета. Довольно ужасно, но на данный момент это кажется единственным выходом.</p><h3 id="запуск-событии-ввода-вывода" tabindex="-1">Запуск событий ввода-вывода <a class="header-anchor" href="#запуск-событии-ввода-вывода" aria-label="Permalink to &quot;Запуск событий ввода-вывода&quot;">​</a></h3><h4 id="анимация" tabindex="-1">Анимация <a class="header-anchor" href="#анимация" aria-label="Permalink to &quot;Анимация&quot;">​</a></h4><p>Теперь начинается НАСТОЯЩЕЕ веселье. Исходный код Dashboard использует событие <code>DOTAGlobalSceneFireEntityInput</code>, которое запускает частицы, например, на кнопке «Домой». По сути, это событие <code>DoEntFire</code> специально для DOTAScenePanel.</p><p>Например, настройте простой <code>&lt;DOTAScenePanel id=&quot;scene&quot; style=&quot;width:400px;height:400px;&quot; map=&quot;background&quot;/&gt;</code> (обратите внимание на <code>id</code>, это очень важно!) еще раз. Но на этот раз измените карту и измените свойство осла <code>Name</code> на <code>donkey</code>, не забудьте перестроить карту. Теперь создайте базовую кнопку панорамы и присвойте ей <code>onactivate=&quot;DOTAGlobalSceneFireEntityInput(scene, donkey, SetAnimation, death)&quot;</code>.</p><p>Теперь, если вы все сделали правильно, ваш осел должен воспроизводить анимацию смерти каждый раз, когда вы нажимаете кнопку. Как? Магия. Но на самом деле обратитесь к части <em>Inputs</em> <a href="https://developer.valvesoftware.com/wiki/Prop_dynamic" target="_blank" rel="noreferrer">this page</a>. Обратите внимание на вход <code>SetAnimation</code>.</p><p>Также обратите внимание, как мы использовали <code>DOTAGlobalSceneFireEntityInput</code> в onactivate, как если бы это была настоящая функция, хотя это не так. Это потому, что групповые мероприятия — это особенные кукурузные хлопья. В javascript панорамы вам нужно использовать <code>$.DispatchEvent(&quot;DOTAGlobalSceneFireEntityInput&quot;, arguments)</code> для достижения того же результата.</p><p>Пример</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>js</span></span>
<span class="line"><span>$.DispatchEvent(</span></span>
<span class="line"><span>  &#39;DOTAGlobalSceneFireEntityInput&#39;,</span></span>
<span class="line"><span>  &#39;LightBuilder&#39;,</span></span>
<span class="line"><span>  &#39;donkey&#39;,</span></span>
<span class="line"><span>  &#39;SetAnimation&#39;,</span></span>
<span class="line"><span>  &#39;spawn&#39;,</span></span>
<span class="line"><span>);</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br></div></div><h4 id="скрипты-скрипты" tabindex="-1">Скрипты? Скрипты! <a class="header-anchor" href="#скрипты-скрипты" aria-label="Permalink to &quot;Скрипты? Скрипты!&quot;">​</a></h4><p>Если бы вы были хорошим мальчиком, вы могли бы обратить внимание на входы <code>RunScriptFile</code> и <code>RunScriptCode</code>.</p><p>Теперь создайте файл <code>donkey.lua</code> в папке <code>vscripts</code> и поместите в него простой <code>print(&quot;Onions have layers, donkey&quot;)</code>.</p><p>Теперь установите для кнопки включения значение <code>DOTAGlobalSceneFireEntityInput(scene, donkey, RunScriptFile, donkey)</code>.</p><p>Обратите внимание на отсутствие расширения файла. Нажмите кнопку еще раз. Вы должны увидеть сообщение в консоли. Поздравляем! Но не слишком волнуйтесь. Да, вы можете выполнить Lua из панорамы. Но это <em>clientside</em>-lua и он <em>очень</em> ограничен. Туда даже нельзя передвигать вещи. Единственное хорошее, что я мог придумать, — это частицы. Недавний патч добавил поддержку ParticleManager в клиентский Lua. Так что теоретически там можно создавать, уничтожать и перемещать разные частицы, а частицы очень мощные.</p><h4 id="родительские-сущности" tabindex="-1">Родительские сущности <a class="header-anchor" href="#родительские-сущности" aria-label="Permalink to &quot;Родительские сущности&quot;">​</a></h4><p>Косметика в Dota работает следующим образом: каждый косметический предмет представляет собой отдельный объект, связанный с героем и прикрепленный к определенной точке крепления с определенными смещениями и углами смещения. И мы тоже можем это сделать! (Ну, частично, по крайней мере)</p><p>Это работает следующим образом: вы выбираете prop_dynamic, в свойствах объекта указываете имя родительского объекта, вставляете <code>Parent Model Bone/Attachment Name</code> (вы можете посмотреть имена вложений в редакторе модели), устанавливаете флажок <code>Use Model Attachment Offset</code> и затем понимаете, что изменение смещения вложений не работает. По крайней мере, на данный момент. Однако изменение углов работает, поэтому есть надежда, что когда-нибудь смещение будет исправлено.</p><p>Вот и все!</p>`,29))])}const k=o(d,[["render",u]]);export{v as __pageData,k as default};
